<script setup>
import {ref} from 'vue'
import {onLoad} from '@dcloudio/uni-app'
import {request} from '@/utils/request'
import {useInteraction} from '@/composables/useInteraction'
import ActionSheet from '@/components/ActionSheet.vue'
import AccessibleButton from '@/components/AccessibleButton.vue'
import Toast from '@/components/Toast.vue'
import XiaotuanPet from '@/components/XiaotuanPet.vue'
import {useToast} from '@/composables/useToast'
const {reducedMotion}=useInteraction()
const toast=useToast()
const id=ref(''),data=ref(null),rating=ref(0),note=ref(''),consent=ref(false),loading=ref(false),saving=ref(false),error=ref(''),saved=ref(false)
const labels=['不太合适','有些不合适','一般','比较合适','很合适']
const path=()=>'/api/growth/programs/'+id.value+'/feedback'
async function load(){loading.value=true;error.value='';try{data.value=await request({url:path()});rating.value=data.value.feedback?.rating||0;note.value=data.value.feedback?.note||'';consent.value=false;saved.value=!!data.value.feedback}catch(e){data.value=null;error.value=e.message||'读取失败，请重试'}finally{loading.value=false}}
async function save(){if(saving.value||!rating.value||!consent.value)return;saving.value=true;error.value='';try{await request({url:path(),method:'PUT',data:{rating:rating.value,note:note.value,consent:consent.value}});await load();toast.success('体验已保存')}catch(e){error.value=e.message||'保存失败，填写的内容仍在'}finally{saving.value=false}}
const confirmingRemove=ref(false)
function remove(){if(saving.value)return;confirmingRemove.value=true}
async function confirmRemove(){if(saving.value)return;confirmingRemove.value=false;saving.value=true;try{await request({url:path(),method:'DELETE'});await load();toast.success('反馈已删除')}catch(e){error.value=e.message||'删除失败'}finally{saving.value=false}}
onLoad(options=>{id.value=options.id||'';if(/^\d+$/.test(id.value))load();else error.value='活动编号无效'})
</script>
<template><view class="growth-page feedback-page" :class="[{'motion-reduced':reducedMotion}, zyThemeClass]"><view class="feedback-hero"><view><text class="growth-eyebrow">PAUSE & REFLECT · 回看这一刻</text><text class="growth-title">体验过后，听听自己</text><text class="growth-subtitle">没有标准答案，真实的感受就很好。</text></view><XiaotuanPet :size="80" face="listen" class="feedback-pet" aria-hidden="true"/></view><view v-if="error" class="growth-error" role="alert">{{error}}<AccessibleButton v-if="!data" class="growth-button secondary" :disabled="loading" @click="load">重试</AccessibleButton></view><view v-if="loading" class="growth-card"><view class="growth-skeleton"/><view class="growth-skeleton short"/></view><template v-else-if="data"><view class="feedback-context"><text class="growth-muted">这次参与</text><text class="context-title">{{data.title}}</text><text v-if="saved" class="saved-badge">已保存 · 可修改或删除</text></view><view v-if="!data.eligible" class="eligibility-note">{{data.reason}}</view><view class="growth-card"><text class="step-number">01 / 体验感受</text><text class="growth-card-title">这次活动适合你吗？</text><text class="growth-muted">评价活动安排与自己的适配程度，不是对自己打分。</text><view class="rating-options"><AccessibleButton v-for="(label,index) in labels" :key="label" :class="['rating-option',{selected:rating===index+1}]" :aria-pressed="rating===index+1" :disabled="saving||!data.eligible" @click="rating=index+1"><text class="rating-number">{{index+1}}</text><text>{{label}}</text></AccessibleButton></view></view><view class="growth-card"><text class="step-number">02 / 留给自己的话</text><text class="growth-card-title">有什么想记住的？<text class="optional">选填</text></text><text class="growth-muted">可以记下一个瞬间、一种材料的触感，或下次想尝试的事。笔记仅你自己可见。</text><textarea v-model="note" maxlength="1000" :disabled="saving||!data.eligible" class="growth-input feedback-note" placeholder="例如：今天愿意慢下来，试着完成一个小步骤。"/><text class="word-count">{{note.length}} / 1000</text></view><view class="privacy-card"><text class="privacy-title">这份记录由你掌握</text><text>{{data.kind==='GUIDANCE'?'一对一的评分和笔记仅本人可见，不向带领者提供评分汇总。':'笔记仅本人可见。至少五位参加者提交后，评分才计入带领者可查看的汇总。'}}</text><text>记录加密保存，可以随时删除。不代表心理状态或治疗效果。</text></view><template v-if="data.eligible"><checkbox-group @change="consent=$event.detail.value.includes('agree')"><label class="growth-consent"><checkbox value="agree" :checked="consent" :disabled="saving" color="#217e76"/><text>我已了解上述可见范围，同意保存这次评分和笔记。</text></label></checkbox-group><AccessibleButton class="growth-button" :disabled="saving||!rating||!consent" @click="save">{{saving?'正在处理…':saved?'更新这次体验':'保存这次体验'}}</AccessibleButton><text v-if="!rating||!consent" class="submit-hint">{{!rating?'请选择一个体验评分':'确认保存授权后即可提交'}}</text></template><AccessibleButton v-if="saved" class="growth-button secondary" :disabled="saving" @click="remove">删除这次反馈</AccessibleButton></template><text class="growth-foot">本系统不能替代专业心理咨询</text><ActionSheet :open="confirmingRemove" title="删除这次反馈？" description="评分和笔记将被删除，也不再计入后续汇总。无法恢复。" :actions="[{key:'confirm',label:'确认删除',tone:'danger',busy:saving}]" cancel-text="再想想" :busy="saving" @select="confirmRemove" @close="confirmingRemove=false"/><Toast/></view></template>
<style src="@/styles/growth.css"></style><style scoped>
/* 令牌化（2026-11-05）：可映射色已全部走 var(--zy-*) 且回退原值（视觉零变化）。
   保留原值三处（无对应令牌，不硬套）：#f4f0e5 hero 渐变暖端（--zy-bg-tint-warm 为 #f7efd9，色偏可见）；
   #587564 次级标注（--zy-text 为 #4a5f54，不同色）；#edf2e9 privacy-card 底（介于 mint 与 bg 之间）。 */
.feedback-page{max-width:850px}.feedback-hero{display:flex;align-items:center;gap:16rpx;margin-bottom:28rpx;padding:30rpx;background:linear-gradient(120deg,var(--zy-bg-tint-mint,#e8efe4),#f4f0e5);border:1rpx solid var(--zy-border,#dfe7dc);border-radius:28rpx}.feedback-hero>view{flex:1}.feedback-pet{flex-shrink:0}.feedback-context{margin:30rpx 0}.context-title{display:block;font-size:32rpx;font-weight:600;line-height:1.6;margin:8rpx 0}.saved-badge{display:inline-block;color:var(--zy-brand-600,#1A645E);background:var(--zy-bg-tint-mint,#e8efe4);padding:8rpx 16rpx;font-size:23rpx;border-radius:10rpx;margin-top:10rpx}.step-number{display:block;color:#587564;letter-spacing:2rpx;font-size:21rpx;margin-bottom:18rpx}.rating-options{display:flex;flex-direction:column;gap:14rpx;margin-top:26rpx}.rating-option{display:flex;align-items:center;gap:20rpx;margin:0;padding:18rpx 24rpx;border:2rpx solid var(--zy-border,#dfe7dc);border-radius:16rpx;background:var(--zy-card-bg,#fff);color:var(--zy-text,#4a5f54);text-align:left;font-size:27rpx;line-height:1.5}.rating-option::after{border:0}.rating-option.selected{background:var(--zy-bg-tint-mint,#e8efe4);border-color:var(--zy-brand-600,#1A645E);color:var(--zy-title,#233d34)}.rating-number{display:flex;align-items:center;justify-content:center;width:48rpx;height:48rpx;background:var(--zy-bg,#f5f7f2);border-radius:12rpx;font-weight:600}.selected .rating-number{background:var(--zy-brand-600,#1A645E);color:white}.optional{font-size:22rpx;font-weight:400;color:var(--zy-text,#4a5f54);margin-left:16rpx}.feedback-note{height:230rpx;line-height:1.8}.word-count{display:block;text-align:right;font-size:22rpx;color:var(--zy-text,#4a5f54)}.privacy-card{display:flex;flex-direction:column;gap:12rpx;border:1rpx solid var(--zy-border,#dfe7dc);background:#edf2e9;border-radius:22rpx;padding:26rpx;font-size:24rpx;line-height:1.8;color:var(--zy-text,#4a5f54)}.privacy-title{font-size:27rpx;font-weight:600;color:var(--zy-title,#233d34)}.eligibility-note{padding:22rpx;background:var(--zy-bg-tint-warm,#f8f0df);color:var(--zy-warning-text,#816027);border-radius:16rpx;font-size:25rpx;line-height:1.7;margin-bottom:24rpx}.submit-hint{display:block;text-align:center;font-size:23rpx;color:var(--zy-text,#4a5f54);margin-top:16rpx}@media(min-width:760px){.rating-options{display:grid;grid-template-columns:repeat(5,1fr)}.rating-option{flex-direction:column;text-align:center;font-size:14px;padding:18px 8px}.feedback-hero image{width:130px;height:160px}}
</style>
